create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','pengawas','madrasah');
create type public.verification_status as enum ('belum','valid','revisi');
create type public.assessment_status as enum ('draft','final');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,nama text not null,email text,role public.user_role not null default 'madrasah',nip text,created_at timestamptz default now());
create table public.madrasah(id uuid primary key default gen_random_uuid(),nsm text unique,npsn text,nama text not null,jenjang text default 'MTs',alamat text,kab_kota text,provinsi text default 'Jawa Timur',kepala_nama text,kepala_nip text,user_id uuid references public.profiles(id),created_at timestamptz default now());
create table public.pengawas(id uuid primary key default gen_random_uuid(),profile_id uuid unique references public.profiles(id) on delete cascade,wilayah text);
create table public.penugasan(id uuid primary key default gen_random_uuid(),pengawas_id uuid references public.pengawas(id) on delete cascade,madrasah_id uuid references public.madrasah(id) on delete cascade,tahun_ajaran text not null,status text default 'aktif',unique(pengawas_id,madrasah_id,tahun_ajaran));
create table public.komponen(id uuid primary key default gen_random_uuid(),kode text unique not null,nama text not null,urutan int default 1);
create table public.indikator(id uuid primary key default gen_random_uuid(),komponen_id uuid references public.komponen(id) on delete cascade,kode text unique not null,indikator text not null,deskripsi text,bobot numeric default 1,skor_min int default 1,skor_max int default 4,urutan int default 1,aktif boolean default true);
create table public.bukti(id uuid primary key default gen_random_uuid(),indikator_id uuid references public.indikator(id) on delete cascade,madrasah_id uuid references public.madrasah(id) on delete cascade,nama_file text,url text,storage_path text,keterangan text,status public.verification_status default 'belum',catatan_verifikator text,uploaded_at timestamptz default now());
create table public.penilaian(id uuid primary key default gen_random_uuid(),indikator_id uuid references public.indikator(id) on delete cascade,madrasah_id uuid references public.madrasah(id) on delete cascade,pengawas_id uuid references public.pengawas(id),skor int,catatan text,status public.assessment_status default 'draft',updated_at timestamptz default now(),unique(indikator_id,madrasah_id));
create table public.rekomendasi(id uuid primary key default gen_random_uuid(),madrasah_id uuid references public.madrasah(id) on delete cascade,pengawas_id uuid references public.pengawas(id),isi text,tanggal date default current_date);
create or replace function public.is_admin() returns boolean language sql stable as $$select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')$$;
create or replace function public.is_pengawas() returns boolean language sql stable as $$select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='pengawas')$$;
alter table public.profiles enable row level security; alter table public.madrasah enable row level security; alter table public.pengawas enable row level security; alter table public.penugasan enable row level security; alter table public.komponen enable row level security; alter table public.indikator enable row level security; alter table public.bukti enable row level security; alter table public.penilaian enable row level security; alter table public.rekomendasi enable row level security;
create policy profiles_self on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy madrasah_access on public.madrasah for all using(user_id=auth.uid() or public.is_admin() or exists(select 1 from public.penugasan x join public.pengawas p on p.id=x.pengawas_id where x.madrasah_id=madrasah.id and p.profile_id=auth.uid())) with check(user_id=auth.uid() or public.is_admin());
create policy pengawas_access on public.pengawas for select using(profile_id=auth.uid() or public.is_admin());
create policy penugasan_access on public.penugasan for all using(public.is_admin() or exists(select 1 from public.pengawas p where p.id=pengawas_id and p.profile_id=auth.uid())) with check(public.is_admin());
create policy component_read on public.komponen for select using(auth.uid() is not null); create policy indicator_read on public.indikator for select using(auth.uid() is not null);
create policy bukti_access on public.bukti for all using(public.is_admin() or madrasah_id in(select id from public.madrasah where user_id=auth.uid()) or exists(select 1 from public.penugasan x join public.pengawas p on p.id=x.pengawas_id where x.madrasah_id=bukti.madrasah_id and p.profile_id=auth.uid())) with check(public.is_admin() or madrasah_id in(select id from public.madrasah where user_id=auth.uid()));
create policy penilaian_access on public.penilaian for all using(public.is_admin() or madrasah_id in(select id from public.madrasah where user_id=auth.uid()) or exists(select 1 from public.pengawas p where p.id=penilaian.pengawas_id and p.profile_id=auth.uid())) with check(public.is_admin() or exists(select 1 from public.pengawas p where p.id=pengawas_id and p.profile_id=auth.uid()));
create policy rekomendasi_access on public.rekomendasi for all using(public.is_admin() or madrasah_id in(select id from public.madrasah where user_id=auth.uid()) or exists(select 1 from public.pengawas p where p.id=pengawas_id and p.profile_id=auth.uid()));
-- Setelah membuat bucket Storage bernama 'bukti-pkkm', buat policy Storage agar user terautentikasi dapat mengelola folder sesuai madrasah.
